ControlPropertyState.AutoRuleBindingString:
Set(varTplSearch, "");
Set(varTplCandidate, Blank());
Set(varShowTplConfirm, false);
Set(varShowTemplatePicker, true)

Set(varChildTitle, Coalesce(varTplCandidate.Title, ""));
Set(varChildDescription, Coalesce(varTplCandidate.Description, ""));
Set(varChildCredits, Coalesce(First(varTplCandidate.Photographer).DisplayName, First(varTplCandidate.Director).DisplayName, First(varTplCandidate.Producer).DisplayName, ""));
Set(varChildLanguageVersions, Coalesce(First(varTplCandidate.LanguageVersions).Value, ""));
Set(varChildContractCase, Coalesce(First(varTplCandidate.ContractCase).Value, ""));
Set(varChildContractCase1Sub, Coalesce(First(varTplCandidate.ContractCase1Sub).Value, ""));
Set(varChildContractRef, Coalesce(varTplCandidate.ContractReference, ""));
Set(varChildModelReleaseProvided, Coalesce(varTplCandidate.ModelReleaseProvided, false));
Set(varChildModelRelease, Coalesce(varTplCandidate.ModelReleaseProvided, false));
Set(varChildMusicUsed, Coalesce(varTplCandidate.MusicUsed, false));
Set(varChildMusicLicenceProvided, Coalesce(varTplCandidate.MusicLicenseProvided, false));
Set(varChildPreexistingProvided, Coalesce(varTplCandidate.PreexistingRightsProvided, false));
Set(varChildPreexisting, Coalesce(varTplCandidate.PreexistingRightsProvided, false));
Set(varChildAIVoiceover, varTplCandidate.AIVoiceover = "Yes");
Set(varShowTplConfirm, false);
Set(varShowTemplatePicker, false)

Set(varTplCandidate, ThisItem);
If(
    varChildTitle <> "" Or varChildDescription <> "",
    Set(varShowTplConfirm, true),
    Set(varChildTitle, Coalesce(varTplCandidate.Title, ""));
    Set(varChildDescription, Coalesce(varTplCandidate.Description, ""));
    Set(varChildCredits, Coalesce(First(varTplCandidate.Photographer).DisplayName, First(varTplCandidate.Director).DisplayName, First(varTplCandidate.Producer).DisplayName, ""));
    Set(varChildLanguageVersions, Coalesce(First(varTplCandidate.LanguageVersions).Value, ""));
    Set(varChildContractCase, Coalesce(First(varTplCandidate.ContractCase).Value, ""));
    Set(varChildContractCase1Sub, Coalesce(First(varTplCandidate.ContractCase1Sub).Value, ""));
    Set(varChildContractRef, Coalesce(varTplCandidate.ContractReference, ""));
    Set(varChildModelReleaseProvided, Coalesce(varTplCandidate.ModelReleaseProvided, false));
    Set(varChildModelRelease, Coalesce(varTplCandidate.ModelReleaseProvided, false));
    Set(varChildMusicUsed, Coalesce(varTplCandidate.MusicUsed, false));
    Set(varChildMusicLicenceProvided, Coalesce(varTplCandidate.MusicLicenseProvided, false));
    Set(varChildPreexistingProvided, Coalesce(varTplCandidate.PreexistingRightsProvided, false));
    Set(varChildPreexisting, Coalesce(varTplCandidate.PreexistingRightsProvided, false));
    Set(varChildAIVoiceover, varTplCandidate.AIVoiceover = "Yes");
    Set(varShowTemplatePicker, false)
)
